# WARNING: These PowerShell scripts were generated by Grok AI and have not been tested.
# They are provided as a starting point for Windows users. After testing on Windows,
# this warning comment can be removed.
#
# Revoke a certificate and regenerate the corresponding CRL
#
# Usage:
#   .\scripts\revoke.ps1 <intermediate-name> <cert-file> [reason]
#
# Examples:
#   .\scripts\revoke.ps1 intermediate-sig end-entity\alice-sig.crt
#   .\scripts\revoke.ps1 intermediate-tls end-entity\server.example.org.crt keyCompromise
#
# Reasons (optional): unspecified, keyCompromise, CACompromise, affiliationChanged,
#                     superseded, cessationOfOperation, certificateHold, removeFromCRL
#

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$CaName,

    [Parameter(Mandatory = $true, Position = 1)]
    [string]$CertFile,

    [Parameter(Position = 2)]
    [string]$Reason = "unspecified"
)

$ErrorActionPreference = "Stop"

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$PKI_ROOT  = Resolve-Path (Join-Path $ScriptDir "..")
Set-Location $PKI_ROOT

if ($env:OPENSSL) {
    $OPENSSL = $env:OPENSSL
} else {
    $OPENSSL = "openssl"
}

if (-not (Test-Path $CaName -PathType Container)) {
    Write-Error "CA directory '$CaName' not found"
    exit 1
}
if (-not (Test-Path $CertFile -PathType Leaf)) {
    Write-Error "Certificate file '$CertFile' not found"
    exit 1
}

Write-Host ">>> Revoking $CertFile under $CaName (reason=$Reason)"

Push-Location $CaName
try {
    # Note: path to cert is relative to the CA directory
    $relCert = Join-Path ".." $CertFile
    & $OPENSSL ca -config openssl.cnf -revoke $relCert -crl_reason $Reason
} finally {
    Pop-Location
}

Write-Host ">>> Regenerating CRL"
Push-Location $CaName
try {
    & $OPENSSL ca -config openssl.cnf -gencrl -out "crl\$CaName.crl.pem"
} finally {
    Pop-Location
}

Write-Host "    Updated $CaName\crl\$CaName.crl.pem"
& $OPENSSL crl -in "$CaName\crl\$CaName.crl.pem" -noout -text | Select-Object -First 20
Write-Host ""
Write-Host "=== Revocation complete ==="
